/**
 * utils.ts — Fungsi utilitas bersama
 */

import type { Margins, MarginUnit } from "./types";
import { POINTS_PER_INCH, MM_PER_INCH, CM_PER_INCH } from "./constants";

// ─── Konversi satuan ──────────────────────────────────────────────

/** Konversi dari satuan margin ke poin (unit internal Office.js) */
export function toPoints(value: number, unit: MarginUnit): number {
  switch (unit) {
    case "in":
      return value * POINTS_PER_INCH;
    case "cm":
      return (value / CM_PER_INCH) * POINTS_PER_INCH;
    case "mm":
      return (value / MM_PER_INCH) * POINTS_PER_INCH;
  }
}

/** Konversi dari poin ke satuan tertentu */
export function fromPoints(points: number, unit: MarginUnit): number {
  switch (unit) {
    case "in":
      return points / POINTS_PER_INCH;
    case "cm":
      return (points / POINTS_PER_INCH) * CM_PER_INCH;
    case "mm":
      return (points / POINTS_PER_INCH) * MM_PER_INCH;
  }
}

/** Konversi mm ke poin */
export function mmToPoints(mm: number): number {
  return (mm / MM_PER_INCH) * POINTS_PER_INCH;
}

/** Konversi poin ke mm */
export function pointsToMm(points: number): number {
  return (points / POINTS_PER_INCH) * MM_PER_INCH;
}

// ─── Validasi margin (PRD §4 Fitur 2D) ───────────────────────────

/**
 * Validasi bahwa margin tidak melebihi ukuran kertas.
 * @returns Pesan error, atau null jika valid
 */
export function validateMargins(
  margins: Margins,
  paperWidthMm: number,
  paperHeightMm: number
): string | null {
  const leftRight = convertToMm(margins.left, margins.unit) + convertToMm(margins.right, margins.unit);
  const topBottom = convertToMm(margins.top, margins.unit) + convertToMm(margins.bottom, margins.unit);

  if (leftRight >= paperWidthMm) {
    return "Margin kiri + kanan melebihi lebar kertas.";
  }
  if (topBottom >= paperHeightMm) {
    return "Margin atas + bawah melebihi tinggi kertas.";
  }
  return null;
}

function convertToMm(value: number, unit: MarginUnit): number {
  switch (unit) {
    case "mm": return value;
    case "cm": return value * 10;
    case "in": return value * MM_PER_INCH;
  }
}

// ─── Nama sheet staging ───────────────────────────────────────────

import { STAGING_PREFIX } from "./constants";

/**
 * Buat nama sheet staging dari indeks antrean.
 * Format: __PS_01, __PS_02, ...
 */
export function makeStagingName(index: number): string {
  return `${STAGING_PREFIX}${String(index + 1).padStart(2, "0")}`;
}

/** Cek apakah nama sheet adalah staging sheet */
export function isStagingSheet(name: string): boolean {
  return name.startsWith(STAGING_PREFIX);
}

// ─── Format angka ─────────────────────────────────────────────────

/** Format angka dengan presisi tertentu, hapus nol di belakang */
export function formatNumber(value: number, precision: number = 1): string {
  return parseFloat(value.toFixed(precision)).toString();
}

/** Format persentase */
export function formatPercent(value: number): string {
  return `${Math.round(value)}%`;
}

// ─── Lain-lain ────────────────────────────────────────────────────

/** Clamp angka ke rentang [min, max] */
export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

/** Delay async (untuk progress UI) */
export function delay(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Gabungkan alamat sheet + range untuk tampilan.
 * Contoh: "Rekap!A1:H45"
 */
export function formatSheetRange(sheetName: string, address: string): string {
  // Jika nama sheet mengandung spasi atau karakter khusus, bungkus dengan kutip
  const needsQuote = /[^A-Za-z0-9_]/.test(sheetName);
  const quoted = needsQuote ? `'${sheetName}'` : sheetName;
  return `${quoted}!${address}`;
}
